    { name = 'Clink to the Past', group = 'Content Quests', desc = 'Start: Dadaroon in Nashmau (H-7). Level 60+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
