    { name = 'Broken Bones', group = 'Content Quests', desc = 'Start: Felyna in Mhaura (G-9). Level 60+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
