    { name = 'Goblin\'s Gambit', group = 'Content Quests', desc = 'Start: Bagatrix in Oldton Movalpolos (G-8). Level 65+. Modes: CW. Repeatable Daily (JP Midnight). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Gold Beastcoin x4' },
            { title = 'Step 1', note = '• More info on the Crystal Warrior Content page' },
            { title = 'Step 2', note = '• Travel to Oldton Movalpolos and talk with Bagatrix.' },
            { title = 'Step 3', note = '• Trade Gold Beastcoin x4 to them.\n    ◦ At minimum one person in the party needs to trade the coins to start the fight. Anyone not trading coins will receive a Dragon Chronicles as their reward.' },
            { title = 'Step 4', note = '• The party will be drawn in to a fight against two goblins (WHM and BST) and a pet bat.\n    ◦ Suggested Order: Bat -> BST (Hog) -> WHM (Long)\n    ◦ WHM will use benediction and cast Cure VI. He can be Silenced and Slept.\n    ◦ BST will not charm, nor resummon pet. Can be Slept.\n    ◦ All goblins use debuff dice. Prepare to wake party with Divine Waltz/Curaga.' },
            { title = 'Step 5', note = '• Once victorious talk with Bagatrix again and choose a reward from one of the three chests.' },
            { title = 'Step 6', note = '• The contents of each chest changes each Vanadiel day. Coordination between party members may be required to sus out which chest holds what type of loot.\n    ◦ One chest contains 1x spell scroll, an augmented weapon, and some miscellaneous items.\n    ◦ Another chest contains 1x trust cipher, an augmented weapon, and some miscellaneous items.\n    ◦ The other chest contains 1x PUP attachment, an augmented weapon, and some miscellaneous items.' },
            { title = 'Reward', note = '• SotS Activity Points\n• Pick from one of three loot chests that change each Vanadiel Day:\n• Attachment Chest:\n• Any attachment from Mnejing\n• Scroll Chest:\n• Black Mage Ancient Magic II Scrolls\n• Red Mage Level 75 Scrolls, Distract & Frazzle.\n• White Mage Level 75 Scrolls\n• Rune Fencer Crusade\n• Trust Chest:\n• Adelheid\n• Elivira\n• Joachim\n• Koru-moru\n• Mihli Aliapoh\n• Uka Totlihn\n• Valaineral' },
    } },
    { name = 'Finding Nemosyne', group = 'System Quests', desc = 'Start: Letheb in Lower Jeuno (H-9). Level 15+. Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
