    { name = 'Digging Up Dirt', group = 'System Quests', desc = 'Start: Sebastian in Lower Jeuno (I-7). Level 30+. Modes: CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
