    { name = 'Boxed Up', group = 'System Quests', desc = 'Start: Rusty Hammer in Northern San d\'Oria (E-3). Level 40+. Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
