    { name = 'Gobbie Travels', group = 'System Quests', desc = 'Start: Portalix in Lower Jeuno (H-9). Level 10+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
