    { name = 'Out of Stock', group = 'System Quests', desc = 'Start: Shady Dealer in Port Bastok (K-13). Level 10+. Modes: ACE WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
