    { name = 'Near Death Experience', group = 'System Quests', desc = 'Start: Andrus in Lufaise Meadows (E-8). Level 60+. Modes: ACE WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
