            { title = 'Step 4', note = '• Inspect the Wool Clump at East Ronfaure (G-8/G-9)' },
            { title = 'Step 5', note = '• Inspect the Wool Clump at East Ronfaure (J-10) which will spawn a hound NM.' },
            { title = 'Step 6', note = '• Defeat te Faarwulv NM in an uncapped fight. It has less than 180hp.' },
            { title = 'Step 7', note = '• Return to Frerehn' },
            { title = 'Reward', note = '• [Augmented] Crossbow\n    ◦ DMG/Resist "Death": +3 AGI+3\n• 600 Gil' },
    } },
    { name = 'Staying Afloat', group = 'San d\'Oria', desc = 'Start: Archimedes in Northern San d\'Oria (F-6). Level 10+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Acorn x12' },
            { title = 'Step 1', note = '• Use Logging or Chocobo Digging in West or East Ronfaure to obtain 12 Acorns.' },
            { title = 'Step 2', note = '• Archimedes keeps track of how many Acorns you have delivered thusfar.' },
            { title = 'Reward', note = '• 800 Gil' },
    } },
    { name = 'Rambling Around', group = 'San d\'Oria', desc = 'Start: Glenda in Southern San d\'Oria (K-8). Level 10+. Modes: CW. Leads to: Rambling Around II. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Fight' },
            { title = 'Step 1', note = '• Talk to Glenda twice and accept the quest.\n    ◦ Glenda is inside of Rosel\'s Armour' },
            { title = 'Step 2', note = '• Go to south H-11 in West Ronfaure.' },
            { title = 'Step 3', note = '• Examine the glowing Ram Wool to spawn and defeat a Wild Ram.\n    ◦ It\'s not level capped.\n    ◦ Wild Ram has around 474 HP.\n    ◦ Wild Ram can use Great Bleat.\n    ◦ Care, at night there will be a Tainted Hound who aggroes by sound.' },
            { title = 'Step 4', note = '• Go back to Glenda.' },
            { title = 'Reward', note = '• 1500 Gil' },
    } },
    { name = 'Rambling Around II', group = 'San d\'Oria', desc = 'Start: Glenda in Southern San d\'Oria (K-8). Level 12+. Modes: CW. Repeatable. After: Rambling Around. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Lanolin x2' },
            { title = 'Step 1', note = '• Glenda will request Lanolin x2.' },
            { title = 'Step 2', note = '• This quest can be repeated, and she keeps track of the number handed in.' },
            { title = 'Reward', note = '• 1800 Gil' },
    } },
    { name = 'Saving My Hide', group = 'San d\'Oria', desc = 'Start: Alutanie in Southern San d\'Oria (D-8). Level 20+. Modes: ACE CW WEW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Fight' },
            { title = 'Step 1', note = '• Talk to Alutanie at D-8 on the balcony of the Leathercrafter\'s Guild.\n    ◦ You must talk to her a 2nd time to accept the quest, you will see Quest Accepted in your chat log' },
            { title = 'Step 2', note = '• Go to Jugner Forest I-6 on the edge of the lake to find Tiger Tracks.' },
            { title = 'Step 3', note = '• When ready click on the tracks and say yes to begin the fight.' },
            { title = 'Step 4', note = '• A Greater Tiger will spawn, no level cap and trust can be used. *roughly 500 hp*' },
            { title = 'Step 5', note = '• Once you kill the tiger click once more on the tracks to receive "a hide of the greater tiger."' },
            { title = 'Step 6', note = '• Return to Alutanie at D-8 for your reward.' },
            { title = 'Reward', note = '• [Augmented] Lizard Belt\n    ◦ HP+5 DEX+2 HP recovered while healing+1' },
    } },
    { name = 'A Matter of Trust (San d\'Oria)', group = 'San d\'Oria', desc = 'Start: Keenajaques in Port San d\'Oria (G-8). Level 10. Modes: CW. Repeatable. Leads to: A Matter of Trust II (San d\'Oria). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Fight' },
            { title = 'Step 1', note = '• Talk to Keenajaques in Port San d\'Oria at G-8 (Inside the Rusty Anchor)' },
            { title = 'Step 2', note = '• Prepare to fight a Crystal Weapon in a Level Synced 10 fight. Crystal Weapon has about 265 HP.' },
            { title = 'Step 3', note = '• Inspect the Crystal Anomaly at La Theine Plateau at L-8/L-9, at the cermet structure behind the Crag of Holla. Select the dialogue option to begin the fight.' },
            { title = 'Step 4', note = '• After defeating the Crystal Weapon, inspect the Crystal Anomaly again for a cutscene.' },
            { title = 'Step 5', note = '• Return to Keenajaques to receive your first trust slot and Trust: Curilla.' },
            { title = 'Reward', note = '• Trust Limit increased to 1\n• Curilla trust\n• [Augmented] Gloves\n    ◦ HP+10' },
    } },
    { name = 'A Matter of Trust II (San d\'Oria)', group = 'San d\'Oria', desc = 'Start: Keenajaques in Port San d\'Oria (G-8). Level 25+. Modes: CW. Repeatable. After: A Matter of Trust (San d\'Oria). Leads to: A Matter of Trust III (San d\'Oria). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Keenajaques in Port San d\'Oria at G-8' },
            { title = 'Step 2', note = '• Enter Ordelle\'s Caves from La Theine Plateau F-7 and travel to I-3 on the first map to find Vertiumaix.' },
            { title = 'Step 3', note = '• When ready and with your trust out speak with Vertumaix to summon a goblin named Snoring Somatix. *He has roughly 400HP*' },
            { title = 'Step 4', note = '• After defeating Somatix talk to Vertiumaix again.\n    ◦ After the fight Vertiumaix will likely have despawned. Move 50 yalms away or zone to bring her back.' },
            { title = 'Step 5', note = '• She will tell you to interact with the glowing spot in front of her to get a "piece of bedrock."' },
            { title = 'Step 6', note = '• Return to Keenajaques and speak with him to hand in the bedrock to finish the quest.' },
            { title = 'Reward', note = '• [Augmented] Cotton Gaiters\n    ◦ DEX+1 MND+2\n• Sprinter\'s Shoes\n    ◦ When you finish all 3 A Matter of Trust II quests' },
    } },
    { name = 'A Matter of Trust III (San d\'Oria)', group = 'San d\'Oria', desc = 'Start: Keenajaques in Port San d\'Oria (G-8). Level 40+. Modes: CW. After: A Matter of Trust II (San d\'Oria). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Speak with Keenajaques again and he will ask that you acquire Sunsand x1 from Valkurm Dunes.\n    ◦ Inspect the boat at H-9 during earth weather to get the sunsand.' },
            { title = 'Step 2', note = '• Trade the sunsand to Keenajaques, and he will ask you to go to Davoi.' },
            { title = 'Step 3', note = '• Inspect the Rendezvous Point on the top of the cliff at H-9. This will spawn two bat trio NM\'s which must be defeated in a level 40 sync\'d fight.\n    ◦ The path up to the point is highly dangerous. A significant number of level 45-49 orcs spawn around the rendezvous point, which should be killed before starting the battle. Consider bringing enough friends to make an alliance -- the quest can be completed in one go by an alliance, as everyone gets credit.\n    ◦ One possible strategy is to start at the bridge at I-10 and clear orcs up to the rendezvous point one or two at a time.' },
            { title = 'Step 4', note = '• Once the bats are defeated, inspect the point again to start a brief cutscene.' },
            { title = 'Step 5', note = '• Return to Keenajaques for your rewards.' },
            { title = 'Reward', note = '• Trust Limit increased to 2\n• Key item San d\'Oria Trust permit\n• Excenmille trust\n• [Augmented] Ram Mantle\n    ◦ DEX+2 AGI+2 HP recovered while healing +2' },
    } },
    { name = 'Chasing the Light', group = 'San d\'Oria', desc = 'Start: Megasolus in North San d\'Oria (M-6). Level 75. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Gold Beastcoin\n• Defeat Dynamis Lord.' },
            { title = 'Step 1', note = '• Speak to Megasolus in the cathedral basement of Northern San d\'Oria (M-8).' },
            { title = 'Step 2', note = '• Travel to Sea Serpent Grotto, and past the Gold Door at (I-14), Map 1.' },
            { title = 'Step 3', note = '• Proceed to Charybdis\' room at (H-11), Map 4 and investigate the Thief\'s Tracks.' },
            { title = 'Step 4', note = '• Talk once more to Megasolus.' },
            { title = 'Step 5', note = '• Visit Misareaux Coast and use the Vortex at (G-5).\n    ◦ Note: This requires having beaten Dynamis Lord before.' },
            { title = 'Step 6', note = '• Investigate the Thief\'s Tracks next to Dremi at (H-10) in Escha - Ru\'Aun.' },
            { title = 'Step 7', note = '• Examine the Crystal Casing at (I-10) to spawn the Eschan Gorger.' },
            { title = 'Step 8', note = '• Return to Megasolus after defeating the Eschan Gorger for your reward.' },
            { title = 'Reward', note = '• Enlight (Scroll) (75 WHM only)' },
    } },
    { name = 'A Crystal Prelude (Bastok)', group = 'Bastok', desc = 'Start: Iron Wolf in Dangruf Wadi (G-8). Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Reward', note = '• JSE Onion Weapon' },
    } },
    { name = 'Running Rings Around', group = 'Bastok', desc = 'Start: Verona in Bastok Markets (K-9). Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Step 1', note = '• Talk to Julberg west in Carmelide\'s Jewelry store @ (I-8) > Then return to Verona,' },
            { title = 'Step 2', note = '• do this back and forth multiple times until you get the ring' },
            { title = 'Reward', note = '• Bastokan Ring' },
    } },
    { name = 'Bug Report', group = 'Bastok', desc = 'Start: Bardus in Port Bastok (K-6). Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Insect Wing x4' },
            { title = 'Step 1', note = '• Return Insect Wing x4. Bardus seems to keep score of how many you\'ve turned in.' },
            { title = 'Reward', note = '• 300 Gil' },
    } },
    { name = 'Birdsearch', group = 'Bastok', desc = 'Start: Neavias in Bastok Markets (H-9). Level 5+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Bird Feather x4' },
            { title = 'Step 1', note = '• After talking to Neavias he requests 4 bird feathers. Trade him 4 for 400g.' },
            { title = 'Reward', note = '• 400 Gil' },
    } },
    { name = 'Mining My Business', group = 'Bastok', desc = 'Start: Iron Digger in Zeruhn Mines (J-9). Level 5+. Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Sweet Lizard x1' },
            { title = 'Step 1', note = '• Speak to Iron Digger in the northwest corner of Zeruhn Mines (J-9). He\'ll ask you to bring him a chunk of Sweet Lizard.\n    ◦ The materials for this can be easily acquired during Gulldago\'s tutorial.' },
            { title = 'Step 2', note = '• Trade him the Sweet Lizard for 36 Pickaxes.' },
            { title = 'Step 3', note = '• If you have already completed Hatchet Job and Reaping Rewards, talk to Crystal Guide book in Provenance to obtain the Field Tunica.' },
            { title = 'Reward', note = '• Pickaxe x36\n• Field Tunica\n    ◦ if you have already completed Hatchet Job and Reaping Rewards' },
    } },
    { name = 'Earthen Echoes', group = 'Bastok', desc = 'Start: Rumbling Valley in Bastok Mines (I-7). Level 15+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Flint Stone x60' },
            { title = 'Step 1', note = '• Talk to Rumbling Valley down the alley' },
            { title = 'Step 2', note = '• Aquire Flint Stone x60 from various means.\n    ◦ Rock Eaters in King Ranperre\'s Tomb (H-6) & (K-6/7) have a 100% drop rate, with a 24% chance at a 2nd Flint Stone)' },
            { title = 'Step 3', note = '• Trade the Flint Stones to Rumbling Valley' },
            { title = 'Reward', note = '• Stoneskin' },
    } },
    { name = 'Buzz Off', group = 'Bastok', desc = 'Start: Sinister Moon in Bastok Mines (K-6). Level 5+. Modes: CW. Leads to: Buzz Kill. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Giant Stinger' },
            { title = 'Step 1', note = '• Talk to Sinister Moon on the top floor' },
            { title = 'Step 2', note = '• Trade him a Giant Stinger' },
            { title = 'Reward', note = '    ◦ [Augmented] Leather Vest\n    ◦ VIT+1 INT+1' },
    } },
    { name = 'Buzz Kill', group = 'Bastok', desc = 'Start: Sinister Moon in Bastok Mines (K-6). Level 10+. Modes: CW. After: Buzz Off. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Fight' },
            { title = 'Step 1', note = '• Sinister Moon will tell you to find a Horrid Hornet up on Vomp Hill by looking for a Sickly Sap.' },
            { title = 'Step 2', note = '• Go onto Vomp Hill 3rd floor (of 4) in South Gustaberg.' },
            { title = 'Step 3', note = '• Go to (I-8) and find a sparkling Sickly Sap at the bottom of a tree.' },
            { title = 'Step 4', note = '• Interacting with it will cap you to level 10 and spawn the NM Horrid Hornet.\n    ◦ Can at least use Pollen.\n    ◦ Has around 175 HP.\n    ◦ Can be easily soloed as skilled-up & equipped MNK/WAR without Hundred Fists.' },
            { title = 'Step 5', note = '• After the battle interact with the Sickly Sap again.' },
            { title = 'Step 6', note = '• Go back to Sinister Moon and get your reward.' },
            { title = 'Reward', note = '• [Augmented] Brass Spear\n    ◦ AGI+2 MND+2' },
    } },
    { name = 'A Little Courage', group = 'Bastok', desc = 'Start: Zorvah in Bastok Mines (I-7). Level ?. Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Fight' },
            { title = 'Step 1', note = '• Find the brave Galka lost in the hills of Gustaberg' },
            { title = 'Step 2', note = '• Talk to Zorvah at Bastok Mines (I-7), on the top floor' },
            { title = 'Step 3', note = '• Inspect the Tiny Breadcrum at South Gustaberg (H-9), at the bottom of the south ramp to Vomp Hill' },
            { title = 'Step 4', note = '• Inspect the Tiny Breadcrum at South Gustaberg (J-8), at the bottom of the ramp to the next level' },
            { title = 'Step 5', note = '• Inspect the Tiny Breadcrum at South Gustaberg (G-8), at the top of the hill which will spawn a quadav NM.' },
            { title = 'Step 6', note = '• Defeat the Duadav Dougher in an uncapped fight. It has less than 180hp.' },
            { title = 'Step 7', note = '• Inspect the Tiny Breadcrum again' },
            { title = 'Reward', note = '• [Augmented] Ash Pole\n    ◦ DMG/Resist "Death": +3 INT+3\n• 600 Gil' },
    } },
    { name = 'Chasing Tails', group = 'Bastok', desc = 'Start: Shining Stone in Bastok Mines (K-7). Level 7+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Lizard Tail x12' },
            { title = 'Step 1', note = '• The Galkachemist asks you to bring him Lizard Tail x12.' },
            { title = 'Step 2', note = '• This quest is repeatable and he will keep track of the number of tails brought.' },
            { title = 'Reward', note = '• 600 Gil' },
    } },
    { name = 'That\'s All Folks', group = 'Bastok', desc = 'Start: Conchata-Potata in Port Bastok (E-6). Level 10+. Modes: CW. Leads to: In a Bucket. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Investigate and Defeat the Gustaberg Hare!' },
            { title = 'Step 1', note = '• Head to South Gustaberg (D-8) The Fumaroles and examine the Hare Tracks. A Gustaberg Hare will spawn(Appx 100-120hp). Return to Conchata for your reward.' },
            { title = 'Reward', note = '• 1500 Gil' },
    } },
    { name = 'In a Bucket', group = 'Bastok', desc = 'Start: Conchata-Potata in Port Bastok (E-6). Level 12+. Modes: CW. Repeatable. After: That\'s All Folks. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Crab Shell x3' },
            { title = 'Step 1', note = '• Conchata-Potata will pay you * 1800 Gil for every three Crab Shell you deliver to him. He keeps track of the total amount delivered.' },
            { title = 'Reward', note = '• 1800 Gil' },
    } },
    { name = 'Wanting Ore', group = 'Bastok', desc = 'Start: Ferredec in Metalworks (F-9). Level 20+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Speak with Ferredec twice (inside the Blacksmith\'s Guild - 1st floor) and select "Let\'s get wet" to accept the quest' },
            { title = 'Step 2', note = '• Travel to (I-7) in Pashhow Marshlands to find a \'Soft Spot\' near the pond\'s edge.' },
            { title = 'Step 3', note = '• Touch the spot to spawn Swamp Scylla, an NM crab with high defense and typical crab abilities.' },
            { title = 'Step 4', note = '• After defeating Swamp Scylla, touch the spot again to receive chunks of swamp ore.' },
            { title = 'Step 5', note = '• Return to Ferredec to receive your reward.' },
            { title = 'Reward', note = '• [Augmented] Plate Belt\n    ◦ HP+10 Accuracy+2\n    ◦ Spell interruption rate down 8%' },
    } },
    { name = 'A Matter of Trust (Bastok)', group = 'Bastok', desc = 'Start: Reisle in Bastok Markets (H-5). Level 10. Modes: CW. Leads to: A Matter of Trust II (Bastok). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Reisle to start the quest. He will ask you to help him in Konschtat Highlands.' },
            { title = 'Step 2', note = '• Examine the Crystal Anomaly on the side of the cermet structure at the South-East corner of K-5 & L-6, behind the mesa, to spawn a Crystal Weapon NM.\n    ◦ There is a normal poltergeist weapon not far from the spot, so be careful if using magic.' },
            { title = 'Step 3', note = '• Examine the spot again after winning to start a short cutscene.' },
            { title = 'Step 4', note = '• Return to Reisle in Bastok to finish the quest.' },
            { title = 'Reward', note = '• Trust Limit increased to 1\n• Volker trust\n• [Augmented] Brass Mittens\n    ◦ HP+10' },
    } },
    { name = 'A Matter of Trust II (Bastok)', group = 'Bastok', desc = 'Start: Reisle in Bastok Markets (H-5). Level 25+. Modes: CW. After: A Matter of Trust (Bastok). Leads to: A Matter of Trust III (Bastok). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Travel to Gusgen Mines and inspect the Upturned Minecart at J-7 to spawn skeleton NM Fear Apparition. After defeating the NM, inspect the cart again and return to Reisle.' },
            { title = 'Reward', note = '• [Augmented] Greaves\n    ◦ HP+10 STR+1 INT+1\n• Sprinter\'s Shoes\n    ◦ When you finish all 3 A Matter of Trust II quests' },
    } },
    { name = 'A Matter of Trust III (Bastok)', group = 'Bastok', desc = 'Start: Reisle in Bastok Markets (H-5). Level 40+. Modes: CW. After: A Matter of Trust II (Bastok). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk with Reisle again, and he will ask you to retrieve a Dangruf Stone x1 for him.' },
            { title = 'Step 2', note = '• After trading him the stone, he asks you to investigate a guard house in Beadeaux. The guard house is located on the upper level at E-7.' },
            { title = 'Step 3', note = '• Inspecting the Guard House will spawn two quadav NM\'s in a level 40 sync\'d fight. You cannot use trusts for this fight. Bring a lot of friends.' },
            { title = 'Step 4', note = '• After the fight Reisle will appear in another mini-cutscene. Return to him one last time in Bastok to receive your rewards.' },
            { title = 'Reward', note = '• Trust Limit increased to 2\n• Key item Bastok Trust permit\n• Naji trust\n• [Augmented] Earth Mantle\n    ◦ STR+2, INT+2, DEF+2' },
    } },
    { name = 'A Crystal Prelude (Windurst)', group = 'Windurst', desc = 'Start: Erudu-Faludu in Toraimarai Canal (H-8). Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Erudu-Faludu to start the quest. Crystal Warrior quests seem to parse without locking movement, so it may seem like nothing has happened when talking to them.' },
            { title = 'Step 2', note = '• He will give you a Sickle to use on (trade to) the Dangling Roots in the room to the west, through the marble door.\n    ◦ It is easily visible and targetable on your left.' },
            { title = 'Step 3', note = '• Trade the Revival Tree Root back to Erudu-Faludu to get your job-specific starting weapon.' },
            { title = 'Step 4', note = '• Talk to Erudu-Faludu again afterward to agree to help with a book.' },
            { title = 'Step 5', note = '• Check the books around the room, and you will eventually spawn a Dusty Tome to fight.' },
            { title = 'Step 6', note = '• Defeat it, talk to Erudu-Faludu, and he will warp you out into East Sarutabaruta with an Adventurer Coupon to trade.\n    ◦ Trade it to Jack of Spades in Windurst Woods (F-8).' },
            { title = 'Reward', note = '• JSE Onion Weapon' },
    } },
    { name = 'Give Me a Ring', group = 'Windurst', desc = 'Start: Moyeyo in Windurst Woods (K-11). Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Moyeyo to start the quest. Again, text will parse without locking movement.' },
            { title = 'Step 2', note = '• Travel to Windurst Walls and examine the Dim Sparkle at (I-4).\n    ◦ Down the ramp, near the water by the House of Heroes.' },
            { title = 'Step 3', note = '• Return to Moyeyo and talk to them again.' },
            { title = 'Step 4', note = '• She will send you over to Abu Dabudabu at (H-9), near the Homepoint crystal.' },
            { title = 'Reward', note = '• Windurstian Ring' },
    } },
    { name = 'Only the Dose', group = 'Windurst', desc = 'Start: Perah Celehsi in Windurst Woods (J-8). Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Giant Stinger' },
            { title = 'Step 1', note = '• Bring Perah Celehsi a Giant Stinger from a bee.' },
            { title = 'Reward', note = '• 300 Gil' },
    } },
    { name = 'Reaping Rewards', group = 'Windurst', desc = 'Start: Fha Mhakyaa in West Sarutabaruta (G-9). Level 5+. Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Honeyed Egg' },
            { title = 'Step 1', note = '• Fha Mhakyaa is up on the cliff at G-9, to which the start of the ramp is up at G-6, G-7.' },
            { title = 'Step 2', note = '• She will ask for a Mug of honeyed egg, which needs to be crafted. It is a level 3 Cooking craft requiring a Water Crystal, Honey, and Bird Egg.\n    ◦ These items can be obtained easily by completing Selele\'s early tasks.' },
            { title = 'Step 3', note = '• If you have already completed Mining My Business and Hatchet Job, talk to Crystal Guide in Provenance to obtain the Field Tunica.' },
            { title = 'Reward', note = '• Sickle x36\n• Field Tunica\n    ◦ if you have already completed Mining My Business and Hatchet Job' },
    } },
    { name = 'Rustling Feathers', group = 'Windurst', desc = 'Start: Puluki-Culuki in Port Windurst (B-4). Level 5+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Yagudo Feather x4' },
            { title = 'Step 1', note = '• Puluki-Culuki requests that you distruptaru the yagudo and bring him Yagudo Feathers x4.' },
            { title = 'Reward', note = '• 150 Gil' },
    } },
    { name = 'Down to Earth', group = 'Windurst', desc = 'Start: Hermin-Harmon in Windurst Waters (F-7). Level 10+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Meteorite' },
            { title = 'Step 1', note = '• Talk to Hermin-Harmon on the western roof of the Optistery.\n    ◦ This is on the north map of Windurst Waters.' },
            { title = 'Step 2', note = '• Trade him a Meteorite obtained from killing Crawlers on Starfall Hillock.' },
            { title = 'Step 3', note = '• He will extract the metal from the meteorite and give it to you, completing the quest.' },
            { title = 'Reward', note = '• Various Ores (Random):\n    ◦ Copper Ore x1\n    ◦ Zinc Ore x1\n    ◦ Gold Ore x1\n    ◦ Platinum Ore x1' },
    } },
    { name = 'Say Peas', group = 'Windurst', desc = 'Start: Perara in Windurst Waters (E-9 (North)). Level 5+. Modes: CW. Leads to: Get Cracking. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Rarab Tail x5' },
            { title = 'Step 1', note = '• Bring Perara Rarab Tail x5.' },
            { title = 'Reward', note = '• 200 Gil\n• [Augmented] Robe\n    ◦ HP+3\n    ◦ MP+3' },
    } },
    { name = 'Get Cracking', group = 'Windurst', desc = 'Start: Perara in Windurst Waters (E-9 (North)). Level 10+. Modes: CW. After: Say Peas. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Travel to H-8 in West Sarutabaruta and investigate the fallen nest under the tree.' },
            { title = 'Step 2', note = '• This will sync the party level to 10 and spawn a level 10 Angry Bird.' },
            { title = 'Step 3', note = '• Defeat the upset avian and investigate the nest again to retrieve the eggs, and return them to Perara.' },
            { title = 'Reward', note = '• 200 Gil\n• [Augmented] Holly Staff\n    ◦ STR+2 MND+2' },
    } },
    { name = 'Slowing Down', group = 'Windurst', desc = 'Start: Temimi in Windurst Woods (I-6). Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Skull Locust x4' },
            { title = 'Step 1', note = '• Talk to Temimi' },
            { title = 'Step 2', note = '• Drop Skull Locust x4 from Yagudo Initiates West Sarutabaruta 1% / West Sarutabaruta (S) 15%' },
            { title = 'Step 3', note = '• HELM West Saurtabaruta & Giddeus' },
            { title = 'Step 4', note = '• Trade the Skull Locusts to Temimi' },
            { title = 'Reward', note = '• Slow' },
    } },
    { name = 'Fowl Tales', group = 'Windurst', desc = 'Start: Hoi-Boi in Windurst Walls (E-7). Level ?. Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Fight' },
            { title = 'Step 1', note = '• Help three Tarutaru brothers return their uncle\'s gold' },
            { title = 'Step 2', note = '• Talk to Hoi-Boi at Windurst Walls (E-7), on top of Koru-Moru\'s Manor' },
            { title = 'Step 3', note = '• Talk to Doi-Boi at Windurst Waters (K-4), behind the Acolyste Hotel' },
            { title = 'Step 4', note = '• Talk to Loi-Boi at Windurst Woods (G-9), in the tall grass in front of the Manustery' },
            { title = 'Step 5', note = '• Inspect with the Buried Treasure at Giddeus (F-4) which will spawn a yagudo NM.' },
            { title = 'Step 6', note = '• Defeat the Yagudo Pilferer NM in an uncapped fight. It has less than 180hp.' },
            { title = 'Step 7', note = '• Inspect the Buried Treasure to obtain a sack of gold coin' },
            { title = 'Step 8', note = '• Return to Hoi-Boi' },
            { title = 'Reward', note = '• [Augmented] Sapara\n    ◦ DMG/Resist "Death": +3 DEX+3\n• 600 Gil' },
    } },
    { name = 'Neck and Neck', group = 'Windurst', desc = 'Start: Erbelie in Windurst Woods (G-8). Level 10+. Modes: CW. Leads to: Neck and Neck II. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Erbelie as she ponders dhalmels, and agree to help her find some evidence of the animals roaming northern Sarutabaruta before the Great War.' },
            { title = 'Step 2', note = '• Travel to I-4/5 in West Sarutabaruta where you\'ll find Dhalmel Bones next to a tree.' },
            { title = 'Step 3', note = '• This will spawn Ghost Dhalmel' },
            { title = 'Step 4', note = '• Return to Erbelie for reward' },
            { title = 'Reward', note = '• 1500 Gil' },
    } },
    { name = 'Neck and Neck II', group = 'Windurst', desc = 'Start: Erbelie in Windurst Woods (G-8). Level 12+. Modes: CW. Repeatable. After: Neck and Neck. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Papaka Grass x2' },
            { title = 'Step 1', note = '• Erbelie: A dhalmel\'s favorite treat is papaka grass. Collect three springs and I\'ll pay.' },
            { title = 'Reward', note = '• 800 Gil' },
    } },
    { name = 'Feather Forecast', group = 'Windurst', desc = 'Start: Pennana in Windurst Woods (G-12). Level 20+. Modes: ACE CW WEW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Fight' },
            { title = 'Step 1', note = '• Speak with Pennana and agree to help her. She will mention that there is a bird with fabulous feathers due in Meriphataud Mountains.\n    ◦ "Look for something shiny to lure outaru the bird-wirdy."' },
            { title = 'Step 2', note = '• Travel to G-10 in Meriphataud Mountains and inspect the Shiny Rock. Because you are, in fact, a bird, you must not only take the shiny object, but also fight a Shrill Jubub for it.' },
            { title = 'Step 3', note = '• Inspect the rock again after the fight, and return to Pennana with it.' },
            { title = 'Reward', note = '• [Augmented] Silver Obi\n    ◦ MP+10\n    ◦ Spell interruption rate down 8%\n    ◦ Pet: Attack+1 Rng.Atk.+1' },
    } },
    { name = 'A Matter of Trust (Windurst)', group = 'Windurst', desc = 'Start: Sharara in Windurst Walls (K-6). Level 10. Modes: CW. Repeatable. Leads to: A Matter of Trust II (Windurst). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Fight' },
            { title = 'Step 1', note = '• Talk to Sharara near the Jeuno consulate.' },
            { title = 'Step 2', note = '• You will receive the message in your log you have accepted the quest.' },
            { title = 'Step 3', note = '• Talk to Sharara again to get a prompt to accept the quest.' },
            { title = 'Step 4', note = '• Travel to the Crag of Mea in Tahrongi Canyon, and investigate the Crystal Anomaly on the north side of the crag, in I-5. This will spawn a Crystal Weapon NM, which must be defeated.' },
            { title = 'Step 5', note = '• Investigate the Anomaly again to get a cutscene.' },
            { title = 'Step 6', note = '• Return to Sharara to complete the quest.' },
            { title = 'Reward', note = '• Trust Limit increased to 1\n• Ajido-Marujido trust\n• [Augmented] Linen Cuffs\n    ◦ MP+10' },
    } },
    { name = 'A Matter of Trust II (Windurst)', group = 'Windurst', desc = 'Start: Sharara in Windurst Walls (K-6). Level 25+. Modes: CW. Repeatable. After: A Matter of Trust (Windurst). Leads to: A Matter of Trust III (Windurst). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Speak with Sharara again and agree to help. Choose "Certainly! in the prompt. You will be sent to the Maze of Shakhrami to collect readings from some strange emanations.' },
            { title = 'Step 2', note = '• Enter the Maze of Shakhrami through Tahrongi Canyon. Inspect the Odd Emanation at F-8 on Map 1, and defend yourself from the source of the emanation.' },
            { title = 'Step 3', note = '• Once the NM is defeated, inspect the point again to collect the readings.' },
            { title = 'Step 4', note = '• Return to Sharara.' },
            { title = 'Reward', note = '• [Augmented] Sandals\n    ◦ MP+10 CHR+2\n• Sprinter\'s Shoes\n    ◦ When you finish all 3 A Matter of Trust II quests' },
    } },
    { name = 'A Matter of Trust III (Windurst)', group = 'Windurst', desc = 'Start: Sharara in Windurst Walls (K-6). Level 40+. Modes: CW. After: A Matter of Trust II (Windurst). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Sharara again and agree to help.' },
            { title = 'Step 2', note = '• Collect and bring a Starfall Tear from the Twinkle Tree in West Sarutabaruta.\n    ◦ The quest "To Catch a Falling Star" must be started before the tree will make the trade.' },
            { title = 'Step 3', note = '• Sharara will then want to travel to Castle Oztroja basement.' },
            { title = 'Step 4', note = '• Prepare for a group fight at sync level 40. Gear appropriately and be properly skilled. 6-man fight suggested.' },
            { title = 'Step 5', note = '• In castle Oztroja, travel to I-8 and open the false lever to fall down.' },
            { title = 'Step 6', note = '• Inside the cavern, interact with the lid (no name) on the floor to fall down to the basement.' },
            { title = 'Step 7', note = '• Clear the basement of yagudo and bat spawns, optionally build more TP outside the tunnel.' },
            { title = 'Step 8', note = '• Interact with the Low Point to spawn 2 NM Yagudo, Yagudo Sage (Job Unknown) and Yagudo Koga (NIN).' },
            { title = 'Step 9', note = '• After the NMs are defeated, interact with the Low Point again for a final cutscene.' },
            { title = 'Step 10', note = '• Return to Sharara for your rewards.' },
            { title = 'Reward', note = '• Trust Limit increased to 2\n• Key item Windurst Trust permit\n• Kupipi trust\n• [Augmented] Tundra Mantle\n    ◦ MND+2 CHR+2 "Conserve MP"+2' },
    } },
    { name = 'Leg Day', group = 'Jeuno', desc = 'Start: Pedro in Port Jeuno (G-8). Level 15+. Modes: CW. Leads to: Leg Day II. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Pedro and accept becoming his research assistant.' },
            { title = 'Step 2', note = '• He asks you to collect a soil sample from the river bank in Davoi.' },
            { title = 'Step 3', note = '• The River Bank can be found at J-11.' },
            { title = 'Reward', note = '• 800 Gil' },
    } },
    { name = 'Leg Day II', group = 'Jeuno', desc = 'Start: Pedro in Port Jeuno (G-8). Level 20+. Modes: CW. After: Leg Day. Leads to: Leg Day III. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• This time Pedro sends you to Beadeaux.' },
            { title = 'Step 2', note = '• The Beadeaux Sludge can be found at G-7.' },
            { title = 'Reward', note = '• 1,600 Gil' },
    } },
    { name = 'Leg Day III', group = 'Jeuno', desc = 'Start: Pedro in Port Jeuno (G-8). Level 25+. Modes: CW. After: Leg Day II. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• As expected Pedro will ask for a sample from Castle Oztroja.' },
            { title = 'Step 2', note = '• The Gravel Sample can be found at I-8 on map #5.\n    ◦ Same room as Quu Domi the Gallant(NM)' },
            { title = 'Reward', note = '• 2,400 Gil' },
    } },
    { name = 'Leg Work', group = 'Jeuno', desc = 'Start: Pedro in Port Jeuno (G-8). Level 35+. Modes: CW. Repeatable. After: Leg Day III. Leads to: Leg Work II. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Next, Pedro sends you to Qufim Island.' },
            { title = 'Step 2', note = '• Locate the Qufim Source at G-6, and defeat the doll that is attracted when you place the device.' },
            { title = 'Reward', note = '• 2,400 Gil\n• [Augmented] Silver Hose\n    ◦ HP+15, STR+2, VIT+2, ATT+3' },
    } },
    { name = 'Leg Work II', group = 'Jeuno', desc = 'Start: Pedro in Port Jeuno (G-8). Level 35+. Modes: CW. Repeatable. After: Leg Work. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Qufim itself is not good enough, so into the tower you go.' },
            { title = 'Step 2', note = '• Enter Delkfutt\'s Tower and take the first left, then go up the stairs.' },
            { title = 'Step 3', note = '• Go to E-8 on map #2 and click the Delkfutt\'s Source' },
            { title = 'Step 4', note = '• Defeat the pot it summons.' },
            { title = 'Step 5', note = '• Return to Pedro' },
            { title = 'Reward', note = '• 2,400 Gil\n• [Augmented] Velvet Slops\n    ◦ MP+15, DEX+2, ATT+4' },
    } },
    { name = 'Decrypting Antiquity', group = 'Jeuno', desc = 'Start: Lectilas in Upper Jeuno (F-7). Level 45+. Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Lectilas and agree to help him.' },
            { title = 'Step 2', note = '• Acquire a Parchment and copy an inscription in The Eldieme Necropolis.\n    ◦ The parchment can be crafted or purchased from Pikini-Mikini in Mhaura.' },
            { title = 'Step 3', note = '• Travel to the main entrance of the necropolis at I-10 in Batallia Downs.' },
            { title = 'Step 4', note = '• Enter the Necropolis and trade the parchment to the Ancient Text at J-8.' },
            { title = 'Step 5', note = '• Return to Lectilas.' },
            { title = 'Reward', note = '• 3,000 Gil' },
    } },
    { name = 'Decrypting Antiquity II', group = 'Jeuno', desc = 'Start: Lectilas in Upper Jeuno (F-7). Level 50+. Modes: CW. Repeatable. After: Decrypting Antiquity. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• LB1 In Defiant Challenge completed\n• Ancient Papyrus x1' },
            { title = 'Step 1', note = '• Delve into The Eldieme Necropolis again and collect an Ancient Papyrus x1.' },
            { title = 'Step 2', note = '• Trade it to Lectilas to receive a random mage\'s scroll.' },
            { title = 'Step 3', note = '• Keeping any scrolls in the Ephemeral Box/Gramateus, or your inventory, will prevent Lectilas from giving you that same scroll again.' },
            { title = 'Reward', note = '• Various Scrolls:\n    ◦ Freeze (Uncommon)\n    ◦ Tornado (Uncommon)\n    ◦ Quake (Uncommon)\n    ◦ Burst (Uncommon)\n    ◦ Flood (Uncommon)\n    ◦ Flare (Uncommon)\n    ◦ Haste (Uncommon)\n    ◦ Protectra IV (Uncommon)\n    ◦ Refresh (Uncommon)\n    ◦ Dispel (Uncommon)\n    ◦ Phalanx (Rare)\n    ◦ Erase (Rare)\n    ◦ Raise II (Rare)\n    ◦ Utsusemi: Ni (Rare)\n    ◦ Dragon Chronicles (Rare)\n    ◦ Maiden\'s Virelai (Rare)\n    ◦ Mage\'s Ballad II (Rare)\n    ◦ Water IV (Very Rare)\n    ◦ Blizzaga III (Very Rare)' },
    } },
    { name = 'Harboring Fugitives', group = 'Jeuno', desc = 'Start: Agent M97 in Lower Jeuno (J-7). Level 50+. Modes: CW. Repeatable Daily (JP midnight). Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Agent M97, and he will ask you to find Dafoe in Castle Zvahl Baileys.' },
            { title = 'Step 2', note = '• Dafoe is located in Zvahl Baileys (E-8) at the Castle Zvahl Keep zoneline.' },
            { title = 'Step 3', note = '• Inspecting Dafoe will spawn a Level Capped 50 Quadav Excision M-72, removing Buffs and Trusts.' },
            { title = 'Step 4', note = '• After killing Excision M-72, inspect Dafoe one more time.\n    ◦ If Dafoe doesn\'t respawn, either walk away 50 yalms and back, or zone out and back in at the top of the stairs.\n    ◦ The confirmation dialog is pretty non-descriptive, but should read "I... can\'t... go on much longer..."' },
            { title = 'Step 5', note = '• Return to Agent M-97 on the Job you want Artifact Armor Quest materials for and talk to him twice.' },
            { title = 'Step 6', note = '• Answer Yes to a vow of silence and inspect the Treasure Coffer.' },
            { title = 'Step 7', note = '• You should receive the artifact armor quest materials and/or a Dragon Chronicles. You will only receive crafting items, nothing else.' },
            { title = 'Reward', note = '• Artifact armor quest materials of associated job' },
    } },
    { name = 'Empty Handed', group = 'Jeuno', desc = 'Start: Faded Footprint in Ru\'Lude Gardens (H-7). Level 25+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Visit each Promyvion zone in the order given (Holla, Dem, Mea)' },
            { title = 'Step 2', note = '• Examine the echo in each zone\n    ◦ Holla at H-6, SW corner, first floor\n    ◦ Dem at K-12, behind the tree, first floor\n    ◦ Mea at F-4, first floor' },
            { title = 'Step 3', note = '• Defeat the NM which spawns\n    ◦ Holla, a thinker named Dwelling Memory\n    ◦ Dem, a gorger named Bursting Memory\n    ◦ Mea, a craver named Piercing Memory' },
            { title = 'Step 4', note = '• Examine the echo again' },
            { title = 'Step 5', note = '• Restoring the Artifacts: Cassus will ask you to bring them to Steel Teeth who is at the Smithing Guild in Mhaura.' },
            { title = 'Step 6', note = '• Steel Teeth will restore each artifact in exchange for the following materials:' },
            { title = 'Step 7', note = '• Shade Tiara - 2 Bitter Memory and 2 Somber Memory' },
            { title = 'Step 8', note = '• Shade Harness - 2 Radiant Memory and 2 Burning Memory' },
            { title = 'Step 9', note = '• Shade Mittens - 2 Profane Memory and 2 Malevolent Memory' },
            { title = 'Step 10', note = '• Shade Tights - 2 Fleeting Memory and 2 Startling Memory' },
            { title = 'Step 11', note = '• Shade Leggings - 2 Malevolent Memory and 2 Fleeting Memory' },
            { title = 'Step 12', note = '• Total: 4 Fleeting Memory, 4 Malevolent Memory, 2 of everything else' },
            { title = 'Reward', note = '• 1,500 Gil\n• [Augmented] Shade Tiara\n    ◦ STR+2 CHR+2\n• [Augmented] Shade Harness\n    ◦ VIT+2 MND+2\n• [Augmented] Shade Mittens\n    ◦ STR+2 INT+2\n• [Augmented] Shade Tights\n    ◦ STR+2 INT+2\n• [Augmented] Shade Leggings\n    ◦ DEX+2 MND+2' },
    } },
    { name = 'Imperial Vault', group = 'Aht Urghan', desc = 'Start: Vault Keeper in Al Zahbi (F-6 by West Gate). Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Jade Idol\n• Carved Runestone\n• Coral Relic\n• Imperial Urn' },
            { title = 'Step 1', note = '• Collect the 4 items\n    ◦ Jade Idol in ??? Incursion\n    ◦ Carved Runestone in ??? Incursion\n    ◦ Coral Relic in Arrapago Reef Incursion\n    ◦ Imperial Urn in any of the Imperial Incursion' },
            { title = 'Step 2', note = '• Trade the 4 items to the Vault Keeper' },
            { title = 'Reward', note = '• 300 Vault Points' },
    } },
    { name = 'Insult to Gingery', group = 'Aht Urghan', desc = 'Start: Gordo-Bordo in Aht Urhgan Whitegate (I-10). Level 40+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Eastern Ginger x4' },
            { title = 'Step 1', note = '• Gordo-Bordo wants 4x Eastern Ginger. They can be very rarely harvested in Bhaflau Thickets or Wajaom Woodlands.' },
            { title = 'Reward', note = '• 600 Gil\n• [Augmented] Sipahi Turban\n    ◦ DEX+2 INT+2' },
    } },
    { name = 'Pecking Battles', group = 'Aht Urghan', desc = 'Start: Vermali in Bhaflau Thickets (I-10). Level 50+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Vermali: Please get rid of these birds! Hand over six Cobrili beaks and I\'ll pay.' },
            { title = 'Step 2', note = '• Vermali: Give me enough and you\'ll earn a special prize! Haha...' },
            { title = 'Step 3', note = '• 1800 Gil for the first turn in.' },
            { title = 'Step 4', note = '• Turn in 100 beaks to receive the Wivre Mask.' },
            { title = 'Reward', note = '• 1,800 Gil\n• [Augmented] Wivre Mask\n    ◦ DEX+3 Accuracy+5' },
    } },
    { name = 'The Purse Strings', group = 'Aht Urghan', desc = 'Start: Carlo in Aht Urghan Whitegate (I-6). Level 10+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Must be on Puppetmaster to start, can change jobs after speaking to Carlo.' },
            { title = 'Step 2', note = '• Carlo will ask you to go steal some gold from the trolls near the Decorative Bronze Gate in Halvung.' },
            { title = 'Step 3', note = '• Enter Halvung from Bhaflau Thickets (F-8) Entrance 2.\n    ◦ Sneak and invisible will be necessary for the run, both through Bhaflau and Halvung.' },
            { title = 'Step 4', note = '• Interact with the Troll Cache near the Decorative Bronze Gate at (L-5) in Halvung to spawn a Troll Treasurer.\n    ◦ This is a level 10 capped fight, and trusts are lost upon pop.\n    ◦ The fight is trivial, the Troll Treasurer has around 100~150hp.' },
            { title = 'Step 5', note = '• Interact with the Troll Cache again after the fight.' },
            { title = 'Step 6', note = '• Return to Carlo for your choice of Automaton Frame items.\n    ◦ Note: It is just the items, NOT the Imperial Currency.\n    ◦ Note for new players: The Saga of the Skyserpent quest provides enough Imperial Standing and a standalone gold coin for the first 30 levels of upgrades, its follow-up quests can further provide enough for the coins for 40/50 heads.' },
            { title = 'Reward', note = '• Valoredge Frame materials and weapon.\n• Sharpshot Frame materials and weapon.\n• Stormwaker Frame materials and accessory.' },
    } },
    { name = 'X Marks the Spot', group = 'Aht Urghan', desc = 'Start: Captain Farrell in Nashmau (G-7). Level 75. Job: COR. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Speak with Captain Farrell in Nashmau as a 75 Corsair to start quest.\n    ◦ Speak to him again and accept the quest.\n    ◦ You may change to any other job after starting it.' },
            { title = 'Step 2', note = '• Proceed Arrapago Reef and to retrieve a map. Located on Map 2 (G-8).\n    ◦ The Illrusi Atoll Staging Point is is recommended.' },
            { title = 'Step 3', note = '• Return to Captain Farrell and speak with them again.' },
            { title = 'Step 4', note = '• Proceed to Talacca Cove (Caedarva Mire HP) and inspect the coffer there to spawn a Lamia NM.\n    ◦ There is no map for the zone, follow the right path along the water.' },
            { title = 'Step 5', note = '• After defeating the NM inspect the coffer again.' },
            { title = 'Step 6', note = '• Return to Captain Farrell to obtain the Caster\'s Die.' },
            { title = 'Reward', note = '• Caster\'s Roll' },
    } },
    { name = 'X Marks the Spot II', group = 'Aht Urghan', desc = 'Start: Captain Farrell in Nashmau (G-7). Level 75. Job: COR. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Complete: X Marks the spot I' },
            { title = 'Step 1', note = '• Speak to Captain Farrell as a 75 Corsair.\n    ◦ Speak to him again and accept the quest.\n    ◦ Once again a job change is fine.' },
            { title = 'Step 2', note = '• Take the boat from Mhaura to Al Zahbi.' },
            { title = 'Step 3', note = '• Inspect the the artifact at the bow of the boat to spawn a Kraken NM.' },
            { title = 'Step 4', note = '• Inspect the artifact again after defeating the NM.' },
            { title = 'Step 5', note = '• Return to Captain Farrell to obtain the Bolter\'s Die.' },
            { title = 'Reward', note = '• Bolter\'s Roll' },
    } },
    { name = 'The Way of Wadi', group = 'Other Areas', desc = 'Start: Passing Sunrise [Galka Footprint] in Dangruf Wadi (I-12). Modes: CW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Interact with the Galka Footprint (I-12) [SW corner of room] to speak with Passing Sunrise (NPC) to begin quest.' },
            { title = 'Step 2', note = '• Sunken Junk (H-11) [NW corner of same room] - Spawns Weary Crab, Examine after defeat for Shattered Sword\n    ◦ Return to Passing Sunrise, tells you to seek out more pieces.' },
            { title = 'Step 3', note = '• Damaged Debris (H-13) [southern tunnel from room] - Spawns Weary Hare, Examine after defeat for haggard hilt.\n    ◦ Return to Passing Sunrise with hilt. Contine seeking.' },
            { title = 'Step 4', note = '• Dusty Rust (J-13) [center of room] - Spawns Weary Worm, Examine after defeat for broken blade.\n    ◦ Return to Galka Footprint spawns Gobby Grindalox.\n    ◦ Examine Galka Footprint a second time for Passing Sunrise to give you an Onion Sword to take to Brave Fang in Metalworks.' },
            { title = 'Step 5', note = '• Talk to Brave Fang, who can be found in the Darksteel Forge (G-9) of Metalworks to receive your final reward: augmented Degen.' },
            { title = 'Reward', note = '• [Augmented] Degen\n    ◦ INT+3 CHR+3\n• [Augmented] Onion Sword\n    ◦ INT-5 CHR-5' },
    } },
    { name = 'Soup of the Day', group = 'Other Areas', desc = 'Start: Cokhe Lokhe in Selbina (J-9). Level 5+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Crab Apron' },
            { title = 'Step 1', note = '• Talk to Cokhe-Lokhe to start the quest.' },
            { title = 'Step 2', note = '• Trade him a Crab Apron for the 500 Gil.' },
            { title = 'Step 3', note = '• This quest can be repeated.' },
            { title = 'Reward', note = '• 500 Gil' },
    } },
    { name = 'Head First', group = 'Other Areas', desc = 'Start: Hume Footprint in Konschtat Highlands (L-8). Level 10+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Magicked Skull' },
            { title = 'Step 1', note = '• Click on the Hume Footprint at Konschtat Highlands (L-8)' },
            { title = 'Step 2', note = '• Obtain a Magicked Skull from the Ghouls in Gusgen Mines' },
            { title = 'Step 3', note = '• Trade the Magicked Skull to the Hume Footprint at Konschtat Highlands (L-8)' },
            { title = 'Reward', note = '• [Augmented] Lizard Mantle\n    ◦ STR+1' },
    } },
    { name = 'Likely Tails', group = 'Other Areas', desc = 'Start: Mithra Tracks in Tahrongi Canyon (J-8). Level 10+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Wild Rabbit Tail' },
            { title = 'Step 1', note = '• Inspecting the tracks will temporarily spawn Shu Rhuli, a mithra, who says she is looking for Wild Rabbit Tails but laments Buburimu Peninsula being too dangerous.' },
            { title = 'Step 2', note = '• Go to Buburimu Peninsula and fight Mighty Rarabs for a Wild Rabbit Tail.' },
            { title = 'Step 3', note = '• Return to the Mithra Tracks and trade it the tail.' },
            { title = 'Reward', note = '• [Augmented] Cotton Cape\n    ◦ MP+5 INT+1' },
    } },
    { name = 'Helping Hands', group = 'Other Areas', desc = 'Start: Manusiel in Selbina (J-9). Level 15+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Damselfly Worm' },
            { title = 'Step 1', note = '• Talk to Manusiel (inside the Shepherd\'s Muster), who requests a damselfly worm.\n    ◦ Note: Trading him the damselfly worm will remove it from your inventory.' },
            { title = 'Step 2', note = '• Upon receiving the worm, Manusiel will ask for damselfly eggs.\n    ◦ These can be found at (G-7) in Valkurm Dunes, in a small nook along the northern wall (behind all the goblins).' },
            { title = 'Step 3', note = '• Summon your trust(s) and inspect the eggs to spawn three unique damselflies.' },
            { title = 'Step 4', note = '• Kill the flies and inspect the eggs again to gather a sample, then return to Manusiel for your reward.' },
            { title = 'Reward', note = '• [Augmented] Lizard Gloves\n    ◦ HP+5 DEX+2 CHR+2' },
    } },
    { name = 'Rolling With Punches', group = 'Other Areas', desc = 'Start: Raving Fist in Mhaura (I-9). Level 20+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Dhalmel Saliva' },
            { title = 'Step 1', note = '• Talk to Raving Fist and he will ask you to bring him a Dhalmel Saliva.' },
            { title = 'Step 2', note = '• Mating Ground I-7, spawns 3 Dhalmels that link with surrounding Dhalmels. Beware of Goblins nearby.' },
            { title = 'Step 3', note = '• After defeating the Dhalmels, inspect the Mating Ground, then return to Raving Fist.' },
            { title = 'Reward', note = '• [Augmented] Cotton Tekko\n    ◦ STR+2 Attack+4 Evasion-4' },
    } },
    { name = 'Running on the Range', group = 'Other Areas', desc = 'Start: Nefari in East Ronfaure (K-4). Level 30+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Note: Sneak and Invisible are recommended.' },
            { title = 'Step 2', note = '• Speak to Nefari, the NPC just next to the Ranguemont Pass zone line. You will be asked to prove that you are capable in battle by finding the Roasted Remains.' },
            { title = 'Step 3', note = '• The Roasted Remains are are in K-5, East Ronfaure (not Ranguemont), in the bottom right of the square (in the corner).' },
            { title = 'Step 4', note = '• Click the Roasted Remains to spawn The Malignant Worm, a Worm type NM easily killable by a Level 30 with a trust out.Once it has been killed return to Nefari.' },
            { title = 'Step 5', note = '• Nefari will now ask you to obtain 5 artifacts in Ranguemont Pass, you need to get them 1 at a time, returning to Nefari with each.' },
            { title = 'Step 6', note = '• The locations of the artifacts are as follows (and you must follow this order)' },
            { title = 'Step 7', note = '• (F-9) = In the top right of the map square, \'Dented Crown\' is on the eastern side of the tunnel in the water. Return to Nefari to hand in.' },
            { title = 'Step 8', note = '• (J-8) = On the Eastern side of the map, \'Ragged Mitts\' are in the pool in the room. Return to Nefari to hand in.' },
            { title = 'Step 9', note = '• (J-10) = The \'Ragged Slacks\' are in the room south of the previous, again in a pool. Return to Nefari once retrieved to hand in.' },
            { title = 'Step 10', note = '• (D-5) = The \'Ragged \'Pumps\' are in the north west room on the map. Return to Nefari to hand in.' },
            { title = 'Step 11', note = '• (H-6) = The \'Ragged \'Tunic\' is in the middle/north room. Return to Nefari to hand in.' },
            { title = 'Step 12', note = '• Once all artifacts are handed to Nefari, the quest is completed.' },
            { title = 'Step 13', note = '• Restoring the Arifacts: Nefari will ask you to bring them to Renovio who is at the Weaver\'s Guild (H-9) in Selbina.' },
            { title = 'Step 14', note = '• Renovio will restore each artifact however will require the following materials:' },
            { title = 'Step 15', note = '• - Garish Crown - 1 Coeurl Whisker, 1 Bloodthread (see tip below), and 1 Beetle Jaw' },
            { title = 'Step 16', note = '• - Garish Tunic - 4 Sheep Wool, 1 Bloodthread, and 1 Sheep Leather' },
            { title = 'Step 17', note = '• - Garish Mitts - 2 Saruta Cotton, 1 Bloodthread' },
            { title = 'Step 18', note = '• - Garish Slacks - 2 Silk threads, 1 Bloodthread, and 1 Sheep Leather' },
            { title = 'Step 19', note = '• - Garish Pumps - 2 Sheep Leather and 1 Bloodthread' },
            { title = 'Step 20', note = '• Trade the items to Renovio to receive each piece of gear. Enjoy!' },
            { title = 'Step 21', note = '• Tip! You can obtain bloodthread by defeating the custom "Frost Diremites" (level 24) located at G-9 in Beaucedine Glacier.' },
            { title = 'Reward', note = '• [Augmented] Garish Crown\n    ◦ MP +5, Attack +2\n• [Augmented] Garish Tunic\n    ◦ HP +15, Accuracy +2\n• [Augmented] Garish Mitts\n    ◦ MP +10, Accuracy +2\n• [Augmented] Garish Slacks\n    ◦ HP+10 Accuracy +3\n• [Augmented] Garish Pumps\n    ◦ MP+5 Attack +2' },
    } },
    { name = 'Searching the Citadel', group = 'Other Areas', desc = 'Start: Cramp in Garlaige Citadel (G-8). Level 30+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Talk to Cramp, who is located right behind the first Banishing Gate.\n    ◦ Obtain a Pouch of weighted stones which can be found at G-8 on Map #1 which allows players to open the Banishing Gates by themselves.' },
            { title = 'Step 2', note = '• She will tell you to slay a raptor NM in Sauromugue Champaign, which can be found at the Creature Tracks at I-9.\n    ◦ Consider bringing some friends. The thunderbolt breath attack can do upwards of 500 damage to a level 50 Curilla trust.' },
            { title = 'Step 3', note = '• Cramp will inform you that the armor pieces you are looking for can be found scattered about the Citadel, in Scrap Piles. She will provide a clue to the next location as you bring her pieces. You must return to her after finding each piece and receive the next clue or you will not be able to collect the next.' },
            { title = 'Step 4', note = '• The first is located at I-8 on Map #4. (Serket Room)' },
            { title = 'Step 5', note = '• The second is located at F-8 on Map #3, right behind Banishing Gate #2.' },
            { title = 'Step 6', note = '• The third is located at G-6 on Map #2, right behind Banishing Gate #3.' },
            { title = 'Step 7', note = '• The fourth is located at I-7 on Map #2.' },
            { title = 'Step 8', note = '• The fifth is located outside in Sauromugue Champaign, through the back entrance, at J-10.' },
            { title = 'Step 9', note = '• Return to Cramp. She will determine the relics too tattered for her to repair.' },
            { title = 'Step 10', note = '• Travel to Renovio in Selbina, located inside the weaver\'s guild salesroom.' },
            { title = 'Step 11', note = '• He requires some materials to repair the equipment:\n    ◦ Seer\'s Crown -- Bone Chip x2\n    ◦ Seer\'s Tunic -- Cotton Cloth x1\n    ◦ Seer\'s Mitts -- Saruta Cotton x2\n    ◦ Seer\'s Slacks -- Grass Cloth x1\n    ◦ Seer\'s Pumps -- Grass Thread x1' },
            { title = 'Reward', note = '• [Augmented] Seer\'s Crown\n    ◦ Conserve MP+2, MP recovered while healing+1\n• [Augmented] Seer\'s Tunic\n    ◦ INT+1, MND+1\n• [Augmented] Seer\'s Mitts\n    ◦ MP+5, Pet: Attack+2, Pet: Ranged Attack+2\n• [Augmented] Seer\'s Slacks\n    ◦ Magic Accuracy+2, Pet: Accuracy+2, Pet:Ranged Accuracy+2\n• [Augmented] Seer\'s Pumps\n    ◦ Magic Accuracy+2, MP recovered while healing+1' },
    } },
    { name = 'Navigating the Nest', group = 'Other Areas', desc = 'Start: Bella in Crawlers\' Nest (J-9). Level 30+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Note: As soon as you talk to Bella, you will automatically be in a Lv 40 cap fight against a lizard NM named Larping Larzy and will likely link with several lizards.\n    ◦ The NM is really easy but the lizards are not.' },
            { title = 'Step 2', note = '• After beating the NM, interact with Bella again.\n    ◦ You\'ll have to collect the 5 damaged pieces of the set one at a time and bring them back to Bella.\n    ◦ You\'ll get a new clue after each turn in.\n    ◦ Each interaction spot is named after the item.' },
            { title = 'Step 3', note = '• First (Buried beret) is north of Bella in the scorpion room, between (I-7) and (J-7). Aggro free with sneak on.' },
            { title = 'Step 4', note = '• Second (Buried gloves) is in the first lizard room on the second map under the ledge (I-8).\n    ◦ You can get to the second map northwest of Bella. Aggro free with sneak on.' },
            { title = 'Step 5', note = '• Third (Buried brais) is under the ledge in the beetle room (H-7) north of the lizard room where you got the gloves.\n    ◦ Beetles aggro on sight so dropping invis here is very risky. Be quick and reapply invis.' },
            { title = 'Step 6', note = '• Fourth (Buried boots) is in the soldier crawler room under the ledge (G-7), just southwest of the beetle room. Aggro free with sneak on.' },
            { title = 'Step 7', note = '• Fifth (Buried doublet) is outside in Rolanberry Fields through the back of the cave.\n    ◦ The exit is northeast of the three ledge rooms with the other items.\n    ◦ The interact is by the lake (D-11).\n    ◦ Interacting will trigger an NM encounter with Misurgh.\n    ◦ Extremely easy with a level 50+ in the group, probably a level 30ish NM. Collect the last item.' },
            { title = 'Step 8', note = '• Make your way back to Bella with the last item. You can grab sneak/invis from the GoV book if you go back into the cave.\n    ◦ She\'ll send you to Renovio in Selbina who can repair your gear if you bring the materials.' },
            { title = 'Step 9', note = '• Materials required (Total): 2 Chocobo Feather, 10 Flax Flower, 5 Saruta Cotton, 3 Sheep Leather' },
            { title = 'Step 10', note = '• Beret: 2 Chocobo Feather, 2 Flax Flower' },
            { title = 'Step 11', note = '• Doublet: 3 Saruta Cotton, 1 Sheep Leather' },
            { title = 'Step 12', note = '• Gloves: 2 Saruta Cotton, 2 Flax Flower' },
            { title = 'Step 13', note = '• Brais: 6 Flax Flower' },
            { title = 'Step 14', note = '• Gaiters: 2 Sheep Leather' },
            { title = 'Reward', note = '• [Augmented] Noct Beret\n    ◦ Crit hit rate+2% Evasion+2\n• [Augmented] Noct Doublet\n    ◦ STR+2 Evasion+5\n• [Augmented] Noct Gloves\n    ◦ DEX+2 Ranged Attack+2\n• [Augmented] Noct Brais\n    ◦ AGI +2 Accuracy+2\n• [Augmented] Noct Gaiters\n    ◦ Accuracy+2 Ranged Attack+2' },
    } },
    { name = 'Negotiating the Necropolis', group = 'Other Areas', desc = 'Start: Aletta in The Eldieme Necropolis (J-8). Level 30+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Travel to the main entrance of The Eldieme Necropolis, at I-10.' },
            { title = 'Step 2', note = '• Talk to Aletta, then go back outside to Batallia Downs to search for her love.' },
            { title = 'Step 3', note = '• Investigate the Scarred Remains on the coast at J-11. Osu, a bee NM will spawn, which must be defeated. It has about 700hp and the fight is uncapped.' },
            { title = 'Step 4', note = '• Check the remains again after winning, then return to Aletta.' },
            { title = 'Step 5', note = '• She will request that you collect the pieces of armor scattered across the Necropolis, and provides clues to their locations after bringing each back in succession.' },
            { title = 'Step 6', note = '• The first, the damaged sallet, is located in the southeastern brazier room at H-9.' },
            { title = 'Step 7', note = '• The second, the damaged gauntlet, is located in the southwestern brazier room at F-9.' },
            { title = 'Step 8', note = '• The third, the damaged hose, is located in the northwestern brazier room at F-7.' },
            { title = 'Step 9', note = '• The fourth, the damaged greaves, is located in the northeastern brazier room H-7.' },
            { title = 'Step 10', note = '• The final piece, the damaged breastplates, is located in the room below the central drop, A, at G-8.\n    ◦ To access the central drop, you will need either a second player to help open the doors, or a Magicked astrolabe Key-item purchased from the NPC Churano-Shurano on top of the Optistery building at (F-8) Windurst Waters(North) for 10,000 Gil.' },
            { title = 'Step 11', note = '• After returning the last one to Aletta she will send you to Steel Teeth, in the Mhaura blacksmith salesroom, to have them repaired.\n    ◦ Eisenschaller requires Iron Ore x2.\n    ◦ Eisenbrust requires Flint Stone x3.\n    ◦ Eisenhentzes requires Rusty Bucket x2.\n    ◦ Eisendiechlings requires Animal Glue x1.\n    ◦ Eisenschuhs requires Cotton Cloth x1.' },
            { title = 'Step 12', note = '• Note: Players who had obtained the rewards before the introduction of the augments can restore the augmented versions from Nemosyne.' },
            { title = 'Reward', note = '• [Augmented] Eisenschaller\n    ◦ MP+5 Attack+2\n• [Augmented] Eisenbrust\n    ◦ HP+15 Accuracy+2\n• [Augmented] Eisenhentzes\n    ◦ MP+10 Accuracy+2\n• [Augmented] Eisendiechlings\n    ◦ HP+10 Accuracy+3\n• [Augmented] Eisenschuhs\n    ◦ MP+5 Attack+2\n• Note: The Eisen set can be equipped on DRK & DRG.' },
    } },
    { name = 'Horutoto Hakken', group = 'Other Areas', desc = 'Start: Gan-Ban in Inner Horutoto Ruins (H-8) (Just past Three Mage Gate). Level 30+. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Enter Inner Horutoto Ruins from East Sarutabaruta J-7' },
            { title = 'Step 2', note = '• Go past the Three Mage Gate\n    ◦ On CatsEyeXI, all players are free to open the gate, even without the Portal Charm!\n    ◦ If you can, warping to the Toraimorai Canal survival guide and heading back into Horutoto is a quick way to get to the quest start.' },
            { title = 'Step 3', note = '• Talk to Gan-Ban, the tarutaru investigator. He will request that you help him investigate a deadly Cardian malfunction from decades ago, and in exchange he will help you uncover a powerful set of equipment.\n    ◦ As with the other lvl 30 gear quests, you must return to Gan-Ban between retrieving each piece.' },
            { title = 'Step 4', note = '• The first piece is located at D-12 on the Beetle\'s Burrow map.' },
            { title = 'Step 5', note = '• The second piece is located at F-9 on the Beetle\'s Burrow map, by the Maltha spawn point.' },
            { title = 'Step 6', note = '• The third piece is located at G-8 on that same map, by the Mahogany Door.' },
            { title = 'Step 7', note = '• The fourth and fifth piece are located behind the Gate of Earth on the Rose Tower North map. Opening the door requires two keys. Gan-Ban has one, and will give it to you if you retrieve the second. That key is found just in front of the Gate of Thunder, at G-7 on the Rose Tower North map. This will trigger a fight with a fomor black mage (level 27, no level cap for the fight)' },
            { title = 'Step 8', note = '• Return to Gan-Ban, and you will be able to open the Gate of Earth (I-7). Enter the small room, flip the switch, and a Cardian enemy will appear (level 30, no level cap for the fight). After the fight, you will receive the final two damaged pieces.' },
            { title = 'Step 9', note = '• Gan-Ban will thank you upon your return, and send you to Renovio in Selbina (Weaver\'s Guild, H-9) for assistance in repairing each of the damaged pieces of the Soil set.' },
            { title = 'Step 10', note = '• Renovio requires specific items for each piece:\n    ◦ Soil Hachimaki: Linen Thread x2.\n    ◦ Soil Gi: Linen Thread x1, Grass Thread x2.\n    ◦ Soil Tekko: Lauan Lumber x2.\n    ◦ Soil Sitabaki: Wool Thread x1.\n    ◦ Soil Kyahan: Cotton Thread x2.' },
            { title = 'Reward', note = '• [Augmented] Soil Hachimaki\n    ◦ Subtle Blow+3, VIT+2\n• [Augmented] Soil Gi\n    ◦ Zanshin+2%, DEX+2\n• [Augmented] Soil Tekko\n    ◦ Hand-to-hand skill +1, Katana skill +1, Great Katana skill +1\n• [Augmented] Soil Sitabaki\n    ◦ Counter +2, AGI+2\n• [Augmented] Soil Kyahan\n    ◦ Subtle Blow+3, STR+2\n• Note: The Soil set can be equipped by PUP as well.' },
    } },
    { name = 'All Thine Heart', group = 'Other Areas', desc = 'Start: Door: Chantry in Northern San d\'Oria (M-7). Level 40+. Modes: CW. Repeatable. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• None' },
            { title = 'Step 1', note = '• Interact with the door in the cathedral, and the voice behind it will request that you seek out the cave-dwelling hermit in Batallia Downs.' },
            { title = 'Step 2', note = '• The hermit is hiding inside a cave at K-7.' },
            { title = 'Step 3', note = '• He will ask you to retrieve a book from Davoi for him. The Abandoned Campsite can be found along the river at H-8. Interact with the Hiding Spot.' },
            { title = 'Step 4', note = '• Return it to the hermit to enjoy a nice little cutscene, and receive both the armor and a book to return to the Sandoria cathedral.' },
            { title = 'Step 5', note = '• Talk to the voice behind door again to receive the wing and complete the quest.' },
            { title = 'Reward', note = '• Icarus Wing\n• [Augmented] Holy Breastplate\n    ◦ MND+3, ACC+5, ATT+5' },
    } },
    { name = 'Runic Insurrection', group = 'Jobs', desc = 'Start: Octavien in Bastok Markets (F-10). Level 75. Modes: ACE CW WEW. Leads to: Forged in Frost and Flame. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Step 1', note = '• Speak to Octavien Bastok Markets (F-10) (above Dragon\'s Claws) as any lv75 job. He will instruct you to visit Hetfield in Chateau d\'Oraguille (H-9) inside the Prince Regent\'s Room.' },
            { title = 'Step 2', note = '• Speak with Hetfield, and he will tell you to travel to Carpenters\' Landing to fetch fireflowers (Northern San d\'Oria Entrance -> Carpenters\' Landing (H-7)).' },
            { title = 'Step 3', note = '• Checking Fireflowers spawns a sandworm NM named Diabolos Minion.\n    ◦ Uncapped fight that will not desummon Trusts.' },
            { title = 'Step 4', note = '• Return to Hetfield after defeating the NM Diabolos Minion.' },
            { title = 'Step 5', note = '• You\'ll be sent to Fort Karugo-Narugo (S) to find the Sun Gate in the top right corner of (J-8) outside.' },
            { title = 'Step 6', note = '• By checking the Sun Gate, you will spawn an NM Diabolos Zealot.\n    ◦ Uncapped fight that will not desummon Trusts.' },
            { title = 'Step 7', note = '• After defeating the NM Diabolos Zealot recheck the Sun Gate, and you\'ll receive the message: "You should report your findings back to Hetfield in Chateau d\'Oraguille."' },
            { title = 'Step 8', note = '• Return and speak with Hetfield.' },
            { title = 'Step 9', note = '• Upon interacting with the door to leave the Prince Regent\'s Room, you\'ll obtain a Sowilo Claymore, a Foil (Scroll) and Job gesture: rune fencer.\n    ◦ Note: If you had obtained the Sowilo Claymore by other means before, you need to drop it before being able to complete this step.' },
            { title = 'Reward', note = '• Unlocks Rune Fencer\n• Foil (Scroll)\n• Sowilo Claymore' },
    } },
    { name = 'Forged in Frost and Flame', group = 'Jobs', desc = 'Start: Octavien in Bastok Markets (F-10). Level 40. Job: RUN. Modes: ACE CW WEW. After: Runic Insurrection. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Step 1', note = '• Note: If players have unlocked the Rune Fencer job without completing Runic Insurrection, they must finish it first before beginning this AF quest.' },
            { title = 'Step 2', note = '• Speak to Octavien Bastok Markets (F-10) (above Dragon\'s Claws) as Rune Fencer lv40+.' },
            { title = 'Step 3', note = '• Speak to Yestin-Ovestin Metalworks (F-8) first floor near HP2' },
            { title = 'Step 4', note = '• Get a flame geode, and go to Ifrit\'s Cauldron (every person doing the quest needs a flame geode)' },
            { title = 'Step 5', note = '• Find the Molten Rift at (E-7) on map 7 (near "H"), need to go around through the raptor area and past a flame spout. Trade the flame geode to the Molten Rift (each person doing the quest needs to do this step or else you\'ll have to do the fight again)' },
            { title = 'Step 6', note = '• After everyone\'s completed the event, click the Molten Rift to spawn a fiery foe of an interesting and unique mob type. Enemy uses AoE fire spells and abilities.\n    ◦ The enemy\'s level seems to scale with player level.' },
            { title = 'Step 7', note = '• During the fight, use the greatsword weaponskill freezebite or frostbite to stagger the enemy. This seems to remove its blaze spikes and lower its defenses. Using freezebite a second time did not stagger it again. After using the WS, the fight was very easy' },
            { title = 'Step 8', note = '• Click the Molten Rift again and retrieve the gem' },
            { title = 'Step 9', note = '• Return to Yestin-Ovestin in the Metalworks' },
            { title = 'Step 10', note = '• Return to Octavien for your reward' },
            { title = 'Reward', note = '• Beorc Sword (Great Sword, Lv40, RUN, DMG:56, Delay:480, Magic Attack Bonus +2, Parrying Skill +3, Rare, Ex)' },
    } },
    { name = 'The Way of the Blade', group = 'Jobs', desc = 'Start: Vaulrien in Lower Jeuno (H-10). Level 50. Job: RUN. Modes: ACE CW WEW. After: Forged in Frost and Flame. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Runic Ingot x4\n• Darksteel Ingot x3\n• Coeurl Hide x2\n• Gold Thread\n• Phil. Stone' },
            { title = 'Step 1', note = '• Note: Players must have completed Forged In Frost And Flame, before beginning this AF quest.' },
            { title = 'Step 2', note = '• Speak to Vaulrien Lower Jeuno (H-10) (inside Gems by Kshama) as Rune Fencer lv50+.' },
            { title = 'Step 3', note = '• He asks you to bring him the following items to craft the Bladedancer Greaves.\n    ◦ Runic Ingot\n    ◦ Darksteel Ingot\n    ◦ Coeurl Hide x2' },
            { title = 'Step 4', note = '• Trade the items to receive your Bladedancer Greaves.' },
            { title = 'Step 5', note = '• Speak to Vaulrien to begin the next part of the quest. He asks you to bring him the following items to craft the Bladedancer Gauntlets.\n    ◦ Runic Ingot\n    ◦ Darksteel Ingot\n    ◦ Gold Thread' },
            { title = 'Step 6', note = '• Trade the items to receive your Bladedancer Gauntlets.' },
            { title = 'Step 7', note = '• Speak to Vaulrien to begin the next part of the quest. He asks you to go to Xarcabard and defeat Rune Wraith.\n    ◦ Head to F-8 in Xarcabard and click the Runic Gate to spawn Rune Wrath.\n    ◦ This fight is trivial as 60 Run with 2 trusts.' },
            { title = 'Step 8', note = '• After defeating Rune Wraith, return to Vaulrien to receive your Bladedancer Helm.' },
            { title = 'Step 9', note = '• Speak to Vaulrien to begin the next part of the quest. He asks you to bring him the following items to craft the Bladedancer Cuisses.\n    ◦ Runic Ingot x2\n    ◦ Darksteel Ingot\n    ◦ Philosopher\'s Stone' },
            { title = 'Step 10', note = '• Trade the items to receive your Bladedancer Cuisses.' },
            { title = 'Step 11', note = '• Speak to Vaulrien to begin the next part of the quest. He asks you to go to Castle Zvahl Baileys to defeat Demon Hexbinder.\n    ◦ Head to H-7, map #2 in Castle Zvahl Baileys. Click on the Runic Circle to spawn Demon Hexbinder.\n    ◦ This fight is trivial as level 60 Run with 2 trusts.' },
            { title = 'Step 12', note = '• After defeating Demon Hexbinder, return to Vaulrien to receive your Bladedancer Breastplate and complete the quest.' },
            { title = 'Step 13', note = '• If you did not receive any item because your inventory was full then free one slot, zone and talk to Vaulrien again.' },
            { title = 'Reward', note = '• Bladedancer Greaves (Feet, Lv52, RUN, DEF:13, HP+10 AGI+3, Spell Interrupt-10% Enmity+1, Rare, Ex)\n• Bladedancer Gauntlets (Hands, Lv54, RUN, DEF:15, HP+12 DEX+3, Accuracy+3 Parrying Skill+5, Rare, Ex)\n• Bladedancer Helm (Head, Lv56, RUN, DEF:22, HP+14 INT+3, Attack+5 Enmity+1, Rare, Ex)\n• Bladedancer Cuisses (Legs, Lv58, RUN, DEF:32, HP+15 VIT+3, Attack+5 Store TP+3, Rare, Ex)\n• Bladedancer Breastplate (Body, Lv60, RUN, DEF:42, HP+18 STR+4, Haste+2% Accuracy+5, Rare, Ex)' },
    } },
    { name = 'The Unnamed Way', group = 'Jobs', desc = 'Start: Master Lao in Windurst Waters (South) (K-8). Modes: ACE CW WEW. Leads to: The Earth Holds Its Breath. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Any Level 75 job.\n• Turtle Shell' },
            { title = 'Step 1', note = '• NOTE: To save time, obtain a Turtle Shell before starting. Turtle Shells may be purchased from the Auction House (Materials ➞ Bonecraft) or the Bonecraft Guild in Windurst Woods.' },
            { title = 'Step 2', note = '• Speak with Master Lao as any lv75 job in Windurst Waters (South), (K-8), Home Point#3.\n    ◦ Located at the end of the dock behind the Rhinostery.\n    ◦ At the far-east side of the map (close to Blacktea River).' },
            { title = 'Step 3', note = '• Trade Master Lao the Turtle Shell.' },
            { title = 'Step 4', note = '• "Listen to the sound..." to spawn and defeat elemental NMs in Uncapped fights in the following order:' },
            { title = 'Step 5', note = '• Investigate Scorched Earth of the Cauldron in Ifrit\'s Cauldron at (G-9) (Lindwurm Map; Map-5), at the lava pit.\n    ◦ Quickest route (have sneak & invisible): Survival Guide > then map reference points K > L > (G-9).\n    ◦ Clear the area then spawn and defeat Baelfyr [resistant to Silence].' },
            { title = 'Step 6', note = '• Dry crumbled earth of Western Altepa Desert (E-9) north of the Oasis of Hubol.\n    ◦ Quickest route: Use Eastern Altepa Survival Guide and zone into Western Altepa at (E-9). Make your way to (E-9) in the South-West part of Western Altepa Desert.\n    ◦ Spawn and defeat Byrgen.' },
            { title = 'Step 7', note = '• Investigate Frozen earth of Uleguerand (D-8)(E-8) border.\n    ◦ Can enter from Xarcabard and take tunnel in lower left. Do not need to go all the way around.\n    ◦ Spawn and defeat Gefyrst [resistant to Silence and Paralyze].' },
            { title = 'Step 8', note = '• Investigate Scattered Earth of Cape Teriggan on the Southwest corner of (G-6) before the tunnel to Frostmane.\n    ◦ Quickest route: Home Point #1 > (It is G-6 but may help to say NW corner of G-7)\n    ◦ Spawn and defeat Ungeweder.\n    ◦ Can open with Sleep II.' },
            { title = 'Step 9', note = '• Return to Master Lao\n    ◦ Rewarded with Matre Bell, Indi-Poison, Job gesture: geomancer, & Luopan.\n    ◦ Note: If you had obtained the Matre Bell by other means before, you need to drop it before being able to complete this step.' },
            { title = 'Reward', note = '• Unlocks Geomancer\n• Matre Bell\n• Indi-Poison' },
    } },
    { name = 'The Earth Holds Its Breath', group = 'Jobs', desc = 'Start: Master Lao in Windurst Waters (South) (K-8). Level 40. Job: GEO. Modes: ACE CW WEW. After: The Unnamed Way. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Step 1', note = '• Notes: If players have unlocked the Geomancer job without completing The Unnamed Way, they must finish it first before beginning this AF quest. You do NOT need to drop the level 1 Matre Bell. If you dropped yours you can buy another from Sylvie for 5k.' },
            { title = 'Step 2', note = '• The quest will send players to confront a noxious threat... which becomes much less deadly with the help of a geo- or indi-enfeeble.' },
            { title = 'Step 3', note = '• Speak with Master Lao as Geomancer lv40+ in Windurst Waters (South), (K-8), Home Point #3. Present day not the past.' },
            { title = 'Step 4', note = '• Head to Norg and talk to Vestavius. He\'s standing on the platform leading to the Captain\'s Hallway.' },
            { title = 'Step 5', note = '• Obtain a Silver Beastcoin at AH and head to Sea Serpent Grotto.' },
            { title = 'Step 6', note = '• Go past the Silver Door to the small room at K-10. Click the Corrupted Earth to spawn Deranged Morbol.\n    ◦ The Morbol will use an instant-kill breath move during the fight unless it is under the effect of a geomancer enfeeble.' },
            { title = 'Step 7', note = '• Note: The fight scales based on your level. I went as 75 Whm/Geo for Indi-Poison. At level 75 with 5 trusts it was an easy fight.' },
            { title = 'Step 8', note = '• (Optional) Go back to Norg and talk to Vestavius for a short dialog.' },
            { title = 'Step 9', note = '• Go back to Master Lao for your two rewards.' },
            { title = 'Reward', note = '• Dowser\'s Wand (Club, Lv40, GEO, DMG:15, Delay:216, INT+2 Magic Accuracy+2, Rare, Ex)\n• Filiae Bell (Handbell, Lv40, GEO, MP+15 MND+1, Rare, Ex)' },
    } },
    { name = 'Echoes of the Earth', group = 'Jobs', desc = 'Start: Nahele in Lower Jeuno (H-9). Level 50. Job: GEO. Modes: ACE CW WEW. After: The Earth Holds its Breath. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Geoweave Thread x6\n• Silk Cloth x2\n• Velvet Cloth\n• Gold Thread\n• Cermet Chunk\n• Carnelian' },
            { title = 'Step 1', note = '• Note: Players must have completed The Earth Holds its Breath, before beginning this AF quest.' },
            { title = 'Step 2', note = '• Speak to Nahele Lower Jeuno (H-9) (inside Othon\'s Garments) as Geomancer lv50+.' },
            { title = 'Step 3', note = '• She asks you to bring her the following items to craft the Tellurist Boots.\n    ◦ Geoweave Thread x2\n    ◦ Silk Cloth\n    ◦ Cermet Chunk' },
            { title = 'Step 4', note = '• Trade the items to receive your Tellurist Boots.' },
            { title = 'Step 5', note = '• Speak to Nahele to begin the next part of the quest. She asks you to bring her the following items to craft the Tellurist Gloves.\n    ◦ Geoweave Thread x2\n    ◦ Velvet Cloth\n    ◦ Gold Thread' },
            { title = 'Step 6', note = '• Trade the items to receive your Tellurist Gloves.' },
            { title = 'Step 7', note = '• Speak to Nahele to begin the next part of the quest. She asks you to go to The Sanctuary of Zi\'tah and defeat Stormtalon.' },
            { title = 'Step 8', note = '• After defeating Stormtalon, return to Nahele to receive your Tellurist Slops.' },
            { title = 'Step 9', note = '• Speak to Nahele to begin the next part of the quest. She asks you to bring her the following items to craft the Tellurist Circlet.\n    ◦ Geoweave Thread x2\n    ◦ Silk Cloth\n    ◦ Carnelian' },
            { title = 'Step 10', note = '• Trade the items to receive your Tellurist Circlet.' },
            { title = 'Step 11', note = '• Speak to Nahele to begin the next part of the quest. She asks you to go to Ro\'Maeve to defeat Petrified Spirit.' },
            { title = 'Step 12', note = '• After defeating Petrified Spirit, return to Nahele to receive your Tellurist Robe and complete the quest.' },
            { title = 'Reward', note = '• Tellurist Boots (Feet, Lv52, GEO, DEF:10, MP+10 AGI+3, Emnity-1 Handbell Skill+3, Rare, Ex)\n• Tellurist Gloves (Hands, Lv54, GEO, DEF:12, MP+12 MND+3, Emnity-1 ConserveMP+3, Rare, Ex)\n• Tellurist Slops (Legs, Lv56, GEO, DEF:25, MP+14 MND+3, Emnity-1 Geomancy Skill+3, Rare, Ex)\n• Tellurist Circlet (Head, Lv58, GEO, DEF:18, MP+15 INT+3, Magic Accuracy+2 Emnity-2, Rare, Ex)\n• Tellurist Robe (Body, Lv60, GEO, DEF:35, MP+20 INT+4, Magic Atk. Bonus+3 Fast Cast+3%, Rare, Ex)' },
    } },
    { name = 'Daddy Issues', group = 'Limit Breaks', desc = 'Start: Brittany in Upper Jeuno (G-7). Level 66+. Job: DNC. Modes: ACE CW WEW. After: The Road to Divadom. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Dancer Main Job lvl66+' },
            { title = 'Step 1', note = '• Interact with Brittany in Upper Jeuno, and she will request that you trade her a Dancer\'s Testimony.' },
            { title = 'Step 2', note = '• Trade her a Dancer\'s Testimony and she\'ll tell you a story.' },
            { title = 'Step 3', note = '• Travel to Jugner Forest (S) K-9 and speak to Mindy. She may appear on the wide scan as Coyote coffer.' },
            { title = 'Step 4', note = '• She will eventually ask if you are ready, and when you are you will be drawn into a fight with a Malboro NM named Daddy.' },
            { title = 'Step 5', note = '• Speak to her again after the fight.' },
            { title = 'Step 6', note = '• Speak to Brittany again in Upper Jeuno G-7 for your reward; Level Cap Will be brought to 75.' },
            { title = 'Reward', note = '• Level cap increased to 75' },
    } },
    { name = 'Immortal Kombat!', group = 'Limit Breaks', desc = 'Start: Nandiyah in Aht Urhgan Whitegate (J-10). Level 66+. Job: BLU. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Blue Mage Main Job Lv.66+' },
            { title = 'Step 1', note = '• Interact with Nandiyah in Aht Urhgan Whitegate' },
            { title = 'Step 2', note = '• Trade him a Blue M. Testimony' },
            { title = 'Step 3', note = '• Travel to Aydeewa Subterrane Map #7 (F-11)\n    ◦ Enter from Wajaom Woodlands (9) (F-11)' },
            { title = 'Step 4', note = '• Talk to Razhud' },
            { title = 'Step 5', note = '• Talk to Razhud again to start a fight' },
            { title = 'Step 6', note = '• Talk to Razhud again after the fight' },
            { title = 'Step 7', note = '• Return to Nandiyah' },
            { title = 'Reward', note = '• Level cap increased to 75' },
    } },
    { name = 'Master of Puppets', group = 'Limit Breaks', desc = 'Start: Kirk in Bastok Markets (F-9). Level 66+. Job: PUP. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Puppetmaster Main Job Lv.66+' },
            { title = 'Step 1', note = '• Interact with Kirk in Bastok Markets' },
            { title = 'Step 2', note = '• Trade him a Pup. Testimony' },
            { title = 'Step 3', note = '• Travel to Caedarva Mire Map #1 (K-5)\n    ◦ Exit from (J-6) Arrapago Reef Map 1 to reach this.\n    ◦ Enter from the zoneline of (I-6) in the Mire.\n    ◦ You will need a Lamian Fang Key to get through the Reef.' },
            { title = 'Step 4', note = '• Talk to Lars' },
            { title = 'Step 5', note = '• Talk to Lars again to start a fight' },
            { title = 'Step 6', note = '• Talk to Lars again after the fight' },
            { title = 'Step 7', note = '• Return to Kirk' },
            { title = 'Reward', note = '• Level cap increased to 75' },
    } },
    { name = 'Missing Rum', group = 'Limit Breaks', desc = 'Start: Jacquotte in Aht Urhgan Whitegate (J-12). Level 66+. Job: COR. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Corsair Main Job Lv.66+' },
            { title = 'Step 1', note = '• Interact with Jacquotte in Aht Urhgan Whitegate' },
            { title = 'Step 2', note = '• Trade him a Cor. Testimony' },
            { title = 'Step 3', note = '• Travel to Arrapago Reef Map #5 (H-8)' },
            { title = 'Step 4', note = '• Talk to Morgan' },
            { title = 'Step 5', note = '• Talk to Morgan again to start a fight' },
            { title = 'Step 6', note = '• Talk to Morgan again after the fight' },
            { title = 'Step 7', note = '• Return to Jacquotte' },
            { title = 'Reward', note = '• Level cap increased to 75' },
    } },
    { name = 'Revenge of the Nerds', group = 'Limit Breaks', desc = 'Start: Lewis in The Eldieme Necropolis (S) (J-8). Level 66+. Job: SCH. Modes: ACE CW WEW. Source: https://www.bg-wiki.com/index.php?title=CatsEyeXI_Systems/Quests', steps = {
            { title = 'Requirements', note = '• Scholar Main Job Lv.66+' },
            { title = 'Step 1', note = '• Interact with Lewis in The Eldieme Necropolis (S)' },
            { title = 'Step 2', note = '• Trade him a Sch. Testimony' },
            { title = 'Step 3', note = '• Travel to Pashhow Marshlands (S) (H-5)\n    ◦ Enter through hidden passage at the corner of G5/6' },
            { title = 'Step 4', note = '• Talk to Poindexter' },
            { title = 'Step 5', note = '• Talk to Poindexter again to start a fight\n    ◦ He will spawn a book which:\n    ◦ Does physical attacks for 50-70\n    ◦ Has a TP move that does massive damage for 400-500, so don\'t get too low.\n    ◦ He can silence. Bring echoes.\n    ◦ First buff up, you\'ll definitely want stoneskin, blink and aquaveil, high interuption when hit\n    ◦ To beat him it required 2 hour, Kaustra him off the bat, then Embrava yourself\n    ◦ After that just cycle through your nukes with Alacrity' },
            { title = 'Step 6', note = '• Talk to Poindexter again after the fight' },
            { title = 'Step 7', note = '• Return to Lewis' },
            { title = 'Reward', note = '• Level cap increased to 75' },
    } },
}

return S
